import{_ as a,o as t,c as r,a2 as n}from"./chunks/framework.BWTY_seE.js";const m=JSON.parse('{"title":"AI 动态 · 2026-11-14","description":"","frontmatter":{"title":"AI 动态 · 2026-11-14","date":"2026-11-14T00:00:00.000Z","outline":[2,3]},"headers":[],"relativePath":"news/2026-11/ai-news-2026-11-14.md","filePath":"news/2026-11/ai-news-2026-11-14.md","lastUpdated":null}'),s={name:"news/2026-11/ai-news-2026-11-14.md"};function o(i,e,l,c,p,d){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="ai-动态-·-2026-11-14" tabindex="-1">AI 动态 · 2026-11-14 <a class="header-anchor" href="#ai-动态-·-2026-11-14" aria-label="Permalink to &quot;AI 动态 · 2026-11-14&quot;">​</a></h1><blockquote><p>截至 2026-11-14。业界 · 产品 · 模型 · 开源 · 开发者工具 · 前端。</p></blockquote><div class="news-briefing" data-section="今日导读"><h2 id="今日导读" tabindex="-1">今日导读 <a class="header-anchor" href="#今日导读" aria-label="Permalink to &quot;今日导读&quot;">​</a></h2><ol><li>今日最大变量来自英伟达：黄仁勋离职引发员工请愿与马斯克声援，同时市场担忧AI初创融资收紧、市值单周蒸发超5730亿美元。</li><li>产品侧OpenAI推出ChatGPT Wallet，让Dots智能体可代用户下单；DeepSeek开放全家桶API，语音能力首次纳入。</li><li>开发者与开源生态活跃：Vercel发布面向编码智能体的UI SDK，Cloudflare开源智能体浏览器引擎Kitesurf，Chrome DevTools MCP等工具持续补齐Agent工程链路。</li></ol></div><div class="news-section" data-section="业界"><h2 id="业界" tabindex="-1">业界 <a class="header-anchor" href="#业界" aria-label="Permalink to &quot;业界&quot;">​</a></h2><h3 id="头条-·-ai-agent-创业公司-langchain-估值达-30-亿美元" tabindex="-1">头条 · AI Agent 创业公司 LangChain 估值达 30 亿美元 <a class="header-anchor" href="#头条-·-ai-agent-创业公司-langchain-估值达-30-亿美元" aria-label="Permalink to &quot;头条 · AI Agent 创业公司 LangChain 估值达 30 亿美元&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-11-14">2026-11-14</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/f0ab2f5e5017.jpg" alt="配图"></p><p>LangChain宣布估值达到30亿美元，其模型与平台无关的Agent管理工具LangSmith已拥有7000家客户。在Agent工具链竞争加剧的背景下，这一数据反映企业侧对可观测与编排层的付费意愿。对读者：评估Agent平台时，可把多模型兼容性与客户规模作为供应商稳定性的参考指标。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/11/13/ai-agent-startup-langchain-hits-3b-valuation/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="产品"><h2 id="产品" tabindex="-1">产品 <a class="header-anchor" href="#产品" aria-label="Permalink to &quot;产品&quot;">​</a></h2><h3 id="chatgpt-wallet上线-ai智能体可代用户购物结账" tabindex="-1">ChatGPT Wallet上线：AI智能体可代用户购物结账 <a class="header-anchor" href="#chatgpt-wallet上线-ai智能体可代用户购物结账" aria-label="Permalink to &quot;ChatGPT Wallet上线：AI智能体可代用户购物结账&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-11-14">2026-11-14</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/2c15d83bd919.jpg" alt="配图"></p><p>ChatGPT Wallet允许AI智能体代用户选购并完成结账，首批面向美国Pro订阅用户限量开放。该功能把Agent能力从信息检索推进到真实支付环节，权限与风控成为关键。对读者：若接入类似代付能力，务必设置单笔限额与二次确认，避免智能体误操作造成资金损失。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/11/13/chatgpts-new-wallet-lets-ai-agents-shop-and-check-out-for-you/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="chatgpt-wallet细节-dots智能体可用信用卡下单-每次结账需生物验证" tabindex="-1">ChatGPT Wallet细节：Dots智能体可用信用卡下单，每次结账需生物验证 <a class="header-anchor" href="#chatgpt-wallet细节-dots智能体可用信用卡下单-每次结账需生物验证" aria-label="Permalink to &quot;ChatGPT Wallet细节：Dots智能体可用信用卡下单，每次结账需生物验证&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-11-14">2026-11-14</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/ceb1497542c0.jpg" alt="配图"></p><p>OpenAI面向美国18岁以上、持美国账单地址及符合条件的Amex、Chase、Mastercard、Visa卡片的ChatGPT Pro用户推出Wallet。添加卡片后，Dots智能体可依提示购买商品，但每次结账前都会与用户确认，并需通过生物识别等安全检查。对读者：可关注其确认与验证流程设计，作为自家Agent支付环节的参考范式。</p><p class="news-entry-source"><a href="https://www.theverge.com/ai-artificial-intelligence/1033425/openai-chatgpt-wallet" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="亚马逊计划构建-world-product-graph-索引全网商品数据" tabindex="-1">亚马逊计划构建“World Product Graph”索引全网商品数据 <a class="header-anchor" href="#亚马逊计划构建-world-product-graph-索引全网商品数据" aria-label="Permalink to &quot;亚马逊计划构建“World Product Graph”索引全网商品数据&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-11-14">2026-11-14</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/04759e19bd25.jpg" alt="配图"></p><p>据路透社报道，亚马逊计划建立覆盖全网在售商品（含其不自营商品）的数据库，并通过自家站点提供信息，项目名为World Product Graph。其意图是减少用户转向Reddit或Google做购前调研，并在AI智能体购物时代掌握商品索引话语权。对读者：做电商或Agent选品的团队应关注该索引的开放程度与接入方式。</p><p class="news-entry-source"><a href="https://www.theverge.com/tech/1033697/amazon-world-product-graph-ai-search" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="模型"><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><h3 id="斯坦福开源memorilla-为冻结llm提供潜在记忆模块" tabindex="-1">斯坦福开源Memorilla：为冻结LLM提供潜在记忆模块 <a class="header-anchor" href="#斯坦福开源memorilla-为冻结llm提供潜在记忆模块" aria-label="Permalink to &quot;斯坦福开源Memorilla：为冻结LLM提供潜在记忆模块&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-11-14">2026-11-14</time></p><p>斯坦福研究者发布开源记忆系统Memorilla，可将文档集合压缩为16个memory token供冻结的Qwen3-8B使用，在FactKG上达到84.33%，所用文档token比全上下文少108倍。该思路为低成本长文档问答提供新路径。对读者：长上下文成本敏感的场景可试验记忆压缩方案，但需先验证自身领域的召回精度。</p><p class="news-entry-source"><a href="https://www.marktechpost.com/2026/11/14/stanford-memorilla-memory-system-16-memory-tokens/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="perplexity发布decider-v1-3-开放权重决策模型新增locate" tabindex="-1">Perplexity发布Decider v1.3：开放权重决策模型新增Locate <a class="header-anchor" href="#perplexity发布decider-v1-3-开放权重决策模型新增locate" aria-label="Permalink to &quot;Perplexity发布Decider v1.3：开放权重决策模型新增Locate&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-11-14">2026-11-14</time></p><p>Perplexity的Decider v1.3与Flash v1.3为开放权重决策模型，输出概率而非文本；v1.3新增用于span抽取的Locate，在63项查询分类任务上报告平均准确率91.6%。对读者：需要路由、分类或置信度打分的系统可评估此类小模型替代通用大模型调用。</p><p class="news-entry-source"><a href="https://www.marktechpost.com/2026/11/13/perplexity-decider-v1-3-open-weight-decision-models-locate/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="_2026年ai视频生成模型盘点-elo、每秒价格与开放权重" tabindex="-1">2026年AI视频生成模型盘点：Elo、每秒价格与开放权重 <a class="header-anchor" href="#_2026年ai视频生成模型盘点-elo、每秒价格与开放权重" aria-label="Permalink to &quot;2026年AI视频生成模型盘点：Elo、每秒价格与开放权重&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-11-14">2026-11-14</time></p><p>MarkTechPost基于Artificial Analysis Video Arena的盲测人类偏好Elo，梳理截至2026年11月13日的视频生成模型排名，指出原生音频已成标配、片段时长15–30秒，且有一款开放权重模型进入前三。对读者：选型时除画质外应同时比较每秒价格与权重开放程度，避免被单一榜单误导。</p><p class="news-entry-source"><a href="https://www.marktechpost.com/2026/11/13/best-ai-video-generation-models-2026/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="开源"><h2 id="开源" tabindex="-1">开源 <a class="header-anchor" href="#开源" aria-label="Permalink to &quot;开源&quot;">​</a></h2><h3 id="chrome-devtools-mcp-让编码智能体接入浏览器调试能力" tabindex="-1">Chrome DevTools MCP：让编码智能体接入浏览器调试能力 <a class="header-anchor" href="#chrome-devtools-mcp-让编码智能体接入浏览器调试能力" aria-label="Permalink to &quot;Chrome DevTools MCP：让编码智能体接入浏览器调试能力&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">ChromeDevTools/chrome-devtools-mcp</span><time datetime="2026-11-14">2026-11-14</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/d5ce33d54261.png" alt="配图"></p><p>ChromeDevTools/chrome-devtools-mcp项目将Chrome DevTools能力提供给编码智能体，使其可在浏览器环境中检查与调试页面。该仓库属于MCP生态中面向前端调试的实用工具。对读者：若智能体需要复现前端问题，可接入该MCP服务补齐运行时观测能力。</p><p class="news-entry-source"><a href="https://github.com/ChromeDevTools/chrome-devtools-mcp" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="阿里开源open-code-review-确定性流水线加llm-agent的代码评审工具" tabindex="-1">阿里开源open-code-review：确定性流水线加LLM Agent的代码评审工具 <a class="header-anchor" href="#阿里开源open-code-review-确定性流水线加llm-agent的代码评审工具" aria-label="Permalink to &quot;阿里开源open-code-review：确定性流水线加LLM Agent的代码评审工具&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">alibaba/open-code-review</span><time datetime="2026-11-14">2026-11-14</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/4d40c3b8de05.png" alt="配图"></p><p>alibaba/open-code-review采用混合架构，将确定性流水线与LLM Agent结合，提供精确到行级的评论，内置多语言规则集覆盖NPE、线程安全、XSS、SQL注入等问题，并兼容OpenAI与Anthropic接口。对读者：可在现有CI中试点该工具，用规则集兜底、LLM补充语义审查。</p><p class="news-entry-source"><a href="https://github.com/alibaba/open-code-review" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="googlechrome开源modern-web-guidance-src-让编码智能体跟上web最佳实践" tabindex="-1">GoogleChrome开源modern-web-guidance-src：让编码智能体跟上Web最佳实践 <a class="header-anchor" href="#googlechrome开源modern-web-guidance-src-让编码智能体跟上web最佳实践" aria-label="Permalink to &quot;GoogleChrome开源modern-web-guidance-src：让编码智能体跟上Web最佳实践&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">GoogleChrome/modern-web-guidance-src</span><time datetime="2026-11-14">2026-11-14</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/00e4d2294b5e.png" alt="配图"></p><p>GoogleChrome发布modern-web-guidance-src仓库，目标是让编码智能体持续获取最新的Web最佳实践。该项目把现代Web平台建议整理为可供智能体消费的内容源。对读者：可将其作为前端智能体的知识来源，减少生成过时API用法的概率。</p><p class="news-entry-source"><a href="https://github.com/GoogleChrome/modern-web-guidance-src" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="开发者工具"><h2 id="开发者工具" tabindex="-1">开发者工具 <a class="header-anchor" href="#开发者工具" aria-label="Permalink to &quot;开发者工具&quot;">​</a></h2><h3 id="vercel发布ui-sdk-为ai编码智能体提供50-ui行为" tabindex="-1">Vercel发布UI SDK：为AI编码智能体提供50+ UI行为 <a class="header-anchor" href="#vercel发布ui-sdk-为ai编码智能体提供50-ui行为" aria-label="Permalink to &quot;Vercel发布UI SDK：为AI编码智能体提供50+ UI行为&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-11-14">2026-11-14</time></p><p>Vercel Labs发布Apache-2.0许可的Vercel UI SDK beta，内含50余种UI行为，编码智能体可将其组合为可访问组件，覆盖React、Vue、Svelte、Solid与Web Components，并提供直接控制UI的桥接能力。对读者：若在搭建生成式前端流水线，可评估该SDK以减少智能体产出组件的可访问性缺陷。</p><p class="news-entry-source"><a href="https://www.marktechpost.com/2026/11/13/vercel-ui-sdk-agent-ui-behaviors/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="cloudflare开源智能体浏览器引擎kitesurf" tabindex="-1">Cloudflare开源智能体浏览器引擎Kitesurf <a class="header-anchor" href="#cloudflare开源智能体浏览器引擎kitesurf" aria-label="Permalink to &quot;Cloudflare开源智能体浏览器引擎Kitesurf&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Cloudflare Blog</span><time datetime="2026-11-14">2026-11-14</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/bd3c1c585c13.png" alt="配图"></p><p>Cloudflare宣布其面向AI智能体的实验性浏览器引擎Kitesurf开源，开发者可查看代码、本地运行，或在Cloudflare Workers上部署自有实例。对读者：需要让Agent执行网页任务的团队可基于该引擎自建沙箱，降低对第三方浏览器服务的依赖。</p><p class="news-entry-source"><a href="https://blog.cloudflare.com/kitesurf-open-source/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="github-actions锁文件功能正式可用-保障工作流依赖安全" tabindex="-1">GitHub Actions锁文件功能正式可用，保障工作流依赖安全 <a class="header-anchor" href="#github-actions锁文件功能正式可用-保障工作流依赖安全" aria-label="Permalink to &quot;GitHub Actions锁文件功能正式可用，保障工作流依赖安全&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-11-14">2026-11-14</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/fe2f53ced36b.webp" alt="配图"></p><p>GitHub于2026年10月28日正式推出Actions工作流依赖锁文件功能，通过.github/workflows/actions.lock固定直接与传递依赖的提交哈希，阻断分支或标签变更引发的供应链攻击，同时工作流仍可保留清晰的标签与分支引用。对读者：建议尽快为关键CI工作流生成锁文件，把依赖固定纳入发布流程。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/XrW1cdg9NFRkemvqLiZc?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="inkitt用智能体自动写pr-模型最简单-难在webhook重复与ci失败" tabindex="-1">Inkitt用智能体自动写PR：模型最简单，难在Webhook重复与CI失败 <a class="header-anchor" href="#inkitt用智能体自动写pr-模型最简单-难在webhook重复与ci失败" aria-label="Permalink to &quot;Inkitt用智能体自动写PR：模型最简单，难在Webhook重复与CI失败&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-11-14">2026-11-14</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/fe2f53ced36b.webp" alt="配图"></p><p>Inkitt构建事件驱动的一次性PR创建器，以状态机编排短生命周期智能体容器，支持断点恢复与安全隔离，日均投入生产使用。其经验是决策逻辑与副作用严格分离、智能体仅获短期凭证、用Git Diff检查约束变更路径。对读者：做自动化PR流水线时，应优先设计幂等与失败恢复，而非纠结模型选型。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/YRXscVHsTh0g6CVCJJ0D?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="前端"><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><h3 id="safari登陆apple-homeview新平台" tabindex="-1">Safari登陆Apple HomeView新平台 <a class="header-anchor" href="#safari登陆apple-homeview新平台" aria-label="Permalink to &quot;Safari登陆Apple HomeView新平台&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">WebKit Blog</span><time datetime="2026-11-14">2026-11-14</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/46c21dba93dd.webp" alt="配图"></p><p>WebKit博客宣布Safari首次进入一个全新平台Apple HomeView，称“浏览器在一个全新平台上开始生活并非每天都有”。这标志着WebKit渲染与浏览器能力向新设备形态延伸。对读者：面向新平台的Web适配可能带来视口、输入与性能约束差异，建议提前做兼容性测试。</p><p class="news-entry-source"><a href="https://webkit.org/blog/18608/safari-on-apple-homeview/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div>',9)])])}const w=a(s,[["render",o]]);export{m as __pageData,w as default};
